import {test,expect,request as pw,type Page} from '@playwright/test';
import {readFile} from 'node:fs/promises';
import {randomBytes,randomUUID} from 'node:crypto';
import type {Locator} from '@playwright/test';
const base=process.env.QA_BASE_URL??'http://localhost:5091';let fixture:any;const cookies:Record<string,any[]>={};
test.beforeAll(async()=>{if(!/^http:\/\/(localhost|127\.0\.0\.1):5091$/.test(base))throw Error('Disposable QA origin required');fixture=JSON.parse(await readFile('../work/platform-browser-fixture.json','utf8'));if(!/^\.data\/platform-qa-\d+$/.test(fixture.path))throw Error('Disposable QA fixture required');for(const role of ['owner','admin']){const context=await pw.newContext({baseURL:base,extraHTTPHeaders:{'x-forwarded-for':'10.'+[...randomBytes(3)].join('.')}});try{expect((await context.post('/api/auth/login',{headers:{Origin:base},data:{email:fixture[role],password:fixture.password}})).ok()).toBeTruthy();cookies[role]=(await context.storageState()).cookies}finally{await context.dispose()}}});
async function login(page:Page,role='owner'){await page.context().addCookies(cookies[role]);await page.addInitScript(()=>localStorage.setItem('dd-working-design-preview','off'));await page.goto(role==='owner'?'/app/overview':'/superadmin');await expect(page.locator(role==='owner'?'.topbar':'.sa-topbar')).toBeVisible()}
async function textContrast(node:Locator){return node.evaluate(element=>{const style=getComputedStyle(element),luminance=(color:string)=>{const channels=color.match(/[\d.]+/g)!.slice(0,3).map(value=>{const c=Number(value)/255;return c<=.04045?c/12.92:((c+.055)/1.055)**2.4});return channels[0]*.2126+channels[1]*.7152+channels[2]*.0722},a=luminance(style.color),b=luminance(style.backgroundColor);return (Math.max(a,b)+.05)/(Math.min(a,b)+.05)})}
test('selected-outlet switch persists and blocks actual order commands, then reopens without changing orders',async({page})=>{
 await login(page);const before=await(await page.request.get('/api/workspace')).json(),outlet=before.outlets.find((row:any)=>row.id===before.outletId),toggle=page.getByRole('switch',{name:'Accept new orders for '+outlet.name,exact:true});await expect(toggle).toHaveAttribute('aria-checked','true');const switchBox=await toggle.boundingBox(),selectBox=await page.getByLabel('Current outlet',{exact:true}).boundingBox();expect(switchBox!.x-selectBox!.x-selectBox!.width).toBeGreaterThanOrEqual(7);expect(Math.abs(switchBox!.y+switchBox!.height/2-selectBox!.y-selectBox!.height/2)).toBeLessThanOrEqual(1);await expect(toggle).toHaveCSS('height','28px');await expect(page.getByLabel('Current outlet',{exact:true})).toHaveCSS('height','28px');await expect(toggle).toHaveCSS('min-width','52px');await expect(toggle.locator('.order-switch-thumb')).toHaveCSS('width','16px');await expect(page.locator('.topbar>.workspace-name')).toHaveCSS('border-top-width','1px');await expect(page.locator('.topbar>.workspace-name')).toHaveCSS('background-color','rgb(246, 250, 242)');await expect(page.locator('.topbar>.workspace-name')).toHaveCSS('height','38px');await expect(page.locator('.workspace-avatar')).toHaveCSS('place-items','center');const avatar=await page.locator('.workspace-avatar').boundingBox(),identity=await page.locator('.topbar>.workspace-name').boundingBox();expect(Math.abs(avatar!.y+avatar!.height/2-identity!.y-identity!.height/2)).toBeLessThanOrEqual(1);expect(Math.abs(selectBox!.y+selectBox!.height/2-identity!.y-identity!.height/2)).toBeLessThanOrEqual(1);
 try{await toggle.click();await expect(toggle).toHaveAttribute('aria-checked','false');await expect(toggle).toHaveCSS('background-color','rgb(169, 52, 52)');await page.reload();await expect(toggle).toHaveAttribute('aria-checked','false');const denied=await page.request.post('/api/commands',{headers:{Origin:base,'Idempotency-Key':randomUUID()},data:{action:'createRound',input:{outletId:before.outletId,type:'TAKEAWAY',items:[{itemId:before.menu[0].id,quantity:1}]}}});expect(denied.status()).toBe(409);expect((await denied.json()).error.code).toBe('OUTLET_ORDERING_PAUSED');const after=await(await page.request.get('/api/workspace')).json();expect(after.orders).toEqual(before.orders);expect(after.outlets.find((row:any)=>row.id===outlet.id).qr_enabled).toBe(outlet.qr_enabled);await page.screenshot({path:'../work/outlet-intake-paused.png',animations:'disabled'})}finally{if(await toggle.getAttribute('aria-checked')==='false'){await toggle.click();await expect(toggle).toHaveAttribute('aria-checked','true')}}await expect(toggle).toHaveCSS('background-color','rgb(36, 115, 68)');await expect(page.locator('.topbar>.notification-bell')).toHaveCSS('width','36px');await page.goto('/app/orders/'+before.orders[0].id);await expect(page.locator('.bill-summary-heading')).toHaveCSS('background-color','rgba(0, 0, 0, 0)');await expect(page.locator('.bill-summary-heading')).toHaveCSS('border-top-width','0px');await expect(page.getByRole('button',{name:'Adjustments',exact:true})).toBeEnabled();
});
test('order header retains metadata, highlights the table and opens customer details through its icon',async({page})=>{
 await login(page);const workspace=await(await page.request.get('/api/workspace')).json();
 const created=await page.request.post('/api/commands',{headers:{Origin:base,'Idempotency-Key':randomUUID()},data:{action:'createRound',input:{outletId:workspace.outletId,type:'TAKEAWAY',items:[{itemId:workspace.menu.find((m:any)=>m.name==='Mint cooler').id,quantity:1}]}}});expect(created.ok()).toBeTruthy();const takeaway=await created.json();
 async function command(action:string,input:any,extra={}){const response=await page.request.post('/api/commands',{headers:{Origin:base,'Idempotency-Key':randomUUID()},data:{action,input,...extra}});expect(response.ok()).toBeTruthy();return response.json()}
 const table=await command('table',{outletId:workspace.outletId,label:'Header '+randomUUID().slice(0,6),seats:2,floor:'Main floor'}),session=await command('openSession',{tableId:table.id,guests:2}),dineIn=await command('createRound',{outletId:workspace.outletId,sessionId:session.id,type:'DINE_IN',customer:{name:'Header Guest',phone:'9123456764'},items:[{itemId:workspace.menu.find((m:any)=>m.name==='Mint cooler').id,quantity:1}]});
 await command('orderPin',{pinned:true,version:Number(dineIn.pin_version??0)},{orderId:dineIn.id});
 for(const [width,height] of [[1440,1000],[390,844]]){
  await page.setViewportSize({width,height});
  for(const row of [dineIn,takeaway]){
   const order=await(await page.request.get('/api/orders/'+row.id)).json();await page.goto('/app/orders/'+row.id);
   const reference=page.locator('.order-header-reference'),table=page.locator('.order-table-heading'),channel=page.getByLabel('Order channel and type',{exact:true});
   await expect(reference.getByLabel('Order number '+order.number,{exact:true})).toHaveText('#'+order.number);await expect(reference.getByLabel('Order number '+order.number,{exact:true})).toHaveCSS('font-size',width<650?'26px':'30px');await expect(reference.locator('time')).toHaveAttribute('datetime',order.created_at);await expect(reference.locator('time')).toContainText(/Mon|Tue|Wed|Thu|Fri|Sat|Sun/);
   await expect(page.locator('.order-summary-strip')).toHaveCount(0);await expect(table).toHaveText(order.table?'Table '+order.table.label:order.type.toLowerCase().replaceAll('_',' ').replace(/\b\w/g,(s:string)=>s.toUpperCase()));await expect(channel).toContainText(' · ');
   const title=await page.getByRole('heading',{name:'Order details',exact:true}).boundingBox(),ref=await reference.boundingBox(),highlight=await table.boundingBox();expect(ref!.x).toBeGreaterThan(title!.x+title!.width);expect(highlight!.y).toBeGreaterThanOrEqual(title!.y+title!.height);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBeTruthy();
   await expect(page.locator('.round-panel .panel-heading h2').first()).toHaveCSS('font-size','18px');await expect(page.locator('.round-panel td strong').first()).toHaveCSS('font-size','16px');
   if(order.pinned){await expect(page.locator('.detail-toolbar .vip-order-marker')).toHaveCSS('border-radius','8px');await expect(page.locator('.detail-toolbar .vip-order-marker')).toHaveCSS('height','32px');await expect(page.locator('.detail-toolbar .order-menu-trigger')).toHaveCSS('height','32px')}
   if(order.customer_snapshot){const card=page.locator('.order-customer-card');await expect(card.locator('.order-customer-contact>strong')).toHaveText(order.customer_snapshot.name);await expect(card.locator('.order-customer-contact>span')).toHaveText(order.customer_snapshot.phone);await expect(card.locator('.order-customer-visits>strong')).toHaveText(String(order.customerVisits??0));await expect(card.locator('.badge')).toHaveCount(0)}
   const summary=page.locator('.total-panel');await expect(summary.locator('.grand-total')).toHaveCSS('background-color','rgb(25, 63, 48)');await expect(summary.locator('.grand-total>strong').last()).toHaveText(new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR',maximumFractionDigits:2}).format(Number(order.totals.outstanding)/100));if(order.customer_snapshot){await summary.getByRole('button',{name:'Coupon',exact:true}).click();await expect(page.getByRole('dialog',{name:'Apply coupon',exact:true})).toBeVisible();await page.getByLabel('Close dialog',{exact:true}).click()}
   const icon=page.locator('.customer-details-trigger');if(await icon.count()){await expect(icon.locator('.icon')).toBeVisible();await expect(icon).toHaveText('');await icon.click();await expect(page.getByRole('dialog')).toBeVisible();await expect(page.getByRole('dialog').getByLabel('Name',{exact:true})).toBeVisible();await page.getByLabel('Close dialog',{exact:true}).click()}
   await page.screenshot({path:'../work/order-header-'+width+'-'+(order.table?'table':'takeaway')+'.png',animations:'disabled'});
   if(order.table){await page.goto('/app/table-billing/'+order.table.id);await expect(page.locator('.order-header-reference')).toContainText('#'+order.number)}
  }
 }
});

