async function command(page:Page,action:string,input:any,extra={}){const response=await page.request.post('/api/commands',{headers:{Origin:base,'Idempotency-Key':randomUUID()},data:{action,input,...extra}});const body=await response.json();expect(response.ok(),JSON.stringify(body)).toBeTruthy();return body}

test('3-inch KOT options filter departments, retain privacy and produce separate or combined roll pages',async({page})=>{
 test.setTimeout(180000);await login(page);let w=await(await page.request.get('/api/workspace')).json();const before=w.outlets.find((o:any)=>o.id===w.outletId);
 async function printMode(mode:string){const current=(await(await page.request.get('/api/workspace')).json()).outlets.find((o:any)=>o.id===w.outletId);await command(page,'outlet',{id:current.id,version:current.version,name:current.name,code:current.code,address:current.address??'',gstin:current.gstin??'',qrEnabled:current.qr_enabled,paymentPolicy:current.payment_policy,taxBps:Number(current.tax_bps),earnBps:Number(current.earn_bps),kotPrintMode:mode})}
 await page.addInitScript(()=>{window.print=()=>{const root=window.parent.document.documentElement;root.dataset.qaKotPrint=String(Number(root.dataset.qaKotPrint??0)+1)}});
 const ticketPage=await page.context().newPage();
 try{
  await printMode('MANUAL');const dishes=[];for(const stream of ['FOOD','BAR']){const name='Print '+stream+' '+randomUUID().slice(0,6);dishes.push({...await command(page,'menu',{outletId:w.outletId,name,category:stream==='BAR'?'Bar':'Food',price:10000,taxBps:0,station:'Print '+stream,unit:'portion',stream}),name})};
  let order=await command(page,'createRound',{outletId:w.outletId,type:'TAKEAWAY',items:dishes.map((dish:any)=>({itemId:dish.id,quantity:1})),customer:{name:'Print QA',phone:'9123456765'}});if(order.rounds[0].kot_status==='HELD')await command(page,'recordPayment',{version:order.rounds[0].version,method:'CASH',amount:Number(order.totals.payable)},{orderId:order.id,roundId:order.rounds[0].id});
  await page.goto('/app/orders/'+order.id);await page.getByRole('button',{name:'Print KOT',exact:true}).click();const dialog=page.getByRole('dialog',{name:'Print KOT',exact:true});await dialog.getByLabel('Food',{exact:true}).uncheck();await dialog.getByLabel('Bar',{exact:true}).uncheck();await expect(dialog.getByRole('button',{name:'Print KOT',exact:true})).toBeDisabled();await dialog.getByLabel('Food',{exact:true}).check();await dialog.getByLabel('One combined KOT',{exact:true}).check();
  const response=page.waitForResponse(r=>r.url().endsWith('/api/commands')&&r.request().postDataJSON()?.action==='kotPrint');await dialog.getByRole('button',{name:'Print KOT',exact:true}).click();const job=await(await response).json();expect(job.ticketIds).toHaveLength(1);await expect(page.locator('html')).toHaveAttribute('data-qa-kot-print','1');await ticketPage.goto(job.url);await expect(ticketPage.locator('html')).toHaveAttribute('data-kot-paper-ready','true');await expect(ticketPage.locator('.kot-group')).toHaveCount(1);await expect(ticketPage.locator('[data-kot-receipt]')).toContainText(dishes[0].name);await expect(ticketPage.locator('[data-kot-receipt]')).not.toContainText(dishes[1].name);
  for(const layout of ['SEPARATE','COMBINED']){
   const job=await command(page,'kotPrint',{streams:['FOOD','BAR'],layout},{orderId:order.id,roundId:order.rounds[0].id});await ticketPage.goto(job.url);await expect(ticketPage.locator('html')).toHaveAttribute('data-kot-paper-ready','true');await expect(ticketPage.locator('.kot-group')).toHaveCount(layout==='SEPARATE'?2:1);await expect(ticketPage.locator('[data-kot-receipt]')).not.toContainText('9123456765');const pdf=await ticketPage.pdf({path:'../work/kot-3inch-'+layout+'.pdf',preferCSSPageSize:true,printBackground:true});const boxes=[...pdf.toString('latin1').matchAll(/\/MediaBox\s*\[\s*0\s+0\s+([\d.]+)\s+([\d.]+)\s*\]/g)];expect(boxes.length).toBe(layout==='SEPARATE'?2:1);for(const box of boxes)expect(Math.abs(Number(box[1])-216)).toBeLessThan(.8);await ticketPage.screenshot({path:'../work/kot-3inch-'+layout+'.png',fullPage:true});
  }
 }finally{await ticketPage.close();await printMode(before.kot_print_mode)}
});

