  for(const card of cards){await card.getByRole('button',{name:'Start preparing',exact:true}).click();const ready=card.getByRole('button',{name:'Mark ready',exact:true});await expect(ready).toBeVisible();expect(await textContrast(ready)).toBeGreaterThanOrEqual(4.5);await ready.click()}
